using System.Net;using System.Net.Http.Json;using Microsoft.AspNetCore.Mvc.Testing;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Shop.Api;using Xunit;
namespace Shop.Tests;
public class DatabaseTests:IAsyncLifetime {
 WebApplicationFactory<Program> app=null!;HttpClient client=null!;
 public async Task InitializeAsync(){var cs=Environment.GetEnvironmentVariable("TEST_SQL_CONNECTION")??throw new Exception("Set TEST_SQL_CONNECTION to a disposable SQL Server database ending in _Tests.");if(!new Microsoft.Data.SqlClient.SqlConnectionStringBuilder(cs).InitialCatalog.EndsWith("_Tests",StringComparison.Ordinal))throw new Exception("Test database must end in _Tests.");
 app=new WebApplicationFactory<Program>().WithWebHostBuilder(b=>b.ConfigureServices(s=>{s.Remove(s.Single(d=>d.ServiceType==typeof(DbContextOptions<ShopDb>)));s.AddDbContext<ShopDb>(o=>o.UseSqlServer(cs));}));client=app.CreateClient();using var scope=app.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<ShopDb>();await db.Database.EnsureDeletedAsync();await db.Database.EnsureCreatedAsync();}
 public Task DisposeAsync(){client.Dispose();app.Dispose();return Task.CompletedTask;}
 CheckoutRequest Cart(params CartLine[] lines)=>new(Guid.NewGuid(),"Test Shopper",lines.ToList());
 async Task<int> Stock(int id){using var s=app.Services.CreateScope();return await s.ServiceProvider.GetRequiredService<ShopDb>().Products.Where(p=>p.Id==id).Select(p=>p.Stock).SingleAsync();}
 async Task<int> Orders(){using var s=app.Services.CreateScope();return await s.ServiceProvider.GetRequiredService<ShopDb>().Orders.CountAsync();}
 [Fact]public async Task Health_reads_database()=>Assert.Equal(HttpStatusCode.OK,(await client.GetAsync("/api/health")).StatusCode);
 [Fact]public async Task Search_pagination(){var d=await client.GetFromJsonAsync<System.Text.Json.JsonElement>("/api/products?search=mug&pageSize=1");Assert.Equal(1,d.GetProperty("total").GetInt32());Assert.Equal("Quiet Morning Mug",d.GetProperty("items")[0].GetProperty("name").GetString());}
 [Fact]public async Task Filter_and_sort(){var d=await client.GetFromJsonAsync<System.Text.Json.JsonElement>("/api/products?category=Desk&sort=price-desc");Assert.Equal(3,d.GetProperty("total").GetInt32());Assert.Equal(68,d.GetProperty("items")[0].GetProperty("price").GetDecimal());}
 [Fact]public async Task Invalid_page()=>Assert.Equal(HttpStatusCode.BadRequest,(await client.GetAsync("/api/products?page=0")).StatusCode);
 [Fact]public async Task Missing_product()=>Assert.Equal(HttpStatusCode.NotFound,(await client.GetAsync("/api/products/9999")).StatusCode);
 [Fact]public async Task Correct_total_and_stock(){var r=await client.PostAsJsonAsync("/api/orders",Cart(new CartLine(2,2)));r.EnsureSuccessStatusCode();var o=(await r.Content.ReadFromJsonAsync<OrderDto>())!;Assert.Equal(36,o.Subtotal);Assert.Equal(41,o.Total);Assert.Equal(22,await Stock(2));Assert.Equal(1,await Orders());}
 [Fact]public async Task Free_shipping(){var r=await client.PostAsJsonAsync("/api/orders",Cart(new CartLine(1,3)));r.EnsureSuccessStatusCode();Assert.Equal(0,(await r.Content.ReadFromJsonAsync<OrderDto>())!.Shipping);}
 [Fact]public async Task Retry_is_idempotent(){var c=Cart(new CartLine(2,1));var a=await client.PostAsJsonAsync("/api/orders",c);var b=await client.PostAsJsonAsync("/api/orders",c);a.EnsureSuccessStatusCode();b.EnsureSuccessStatusCode();Assert.Equal((await a.Content.ReadFromJsonAsync<OrderDto>())!.Id,(await b.Content.ReadFromJsonAsync<OrderDto>())!.Id);Assert.Equal(23,await Stock(2));Assert.Equal(1,await Orders());}
 [Fact]public async Task Key_cannot_be_reused_for_different_cart(){var c=Cart(new CartLine(2,1));await client.PostAsJsonAsync("/api/orders",c);Assert.Equal(HttpStatusCode.Conflict,(await client.PostAsJsonAsync("/api/orders",c with{Items=[new(2,2)]})).StatusCode);Assert.Equal(23,await Stock(2));}
 [Fact]public async Task Entire_transaction_rolls_back(){var r=await client.PostAsJsonAsync("/api/orders",Cart(new CartLine(1,1),new CartLine(6,1)));Assert.Equal(HttpStatusCode.Conflict,r.StatusCode);Assert.Equal(18,await Stock(1));Assert.Equal(0,await Orders());}
 [Fact]public async Task Invalid_quantity_writes_nothing(){Assert.Equal(HttpStatusCode.BadRequest,(await client.PostAsJsonAsync("/api/orders",Cart(new CartLine(1,0)))).StatusCode);Assert.Equal(0,await Orders());}
 [Fact]public async Task Concurrent_checkouts_cannot_oversell(){using(var s=app.Services.CreateScope())await s.ServiceProvider.GetRequiredService<ShopDb>().Products.Where(p=>p.Id==1).ExecuteUpdateAsync(u=>u.SetProperty(p=>p.Stock,1));var rs=await Task.WhenAll(client.PostAsJsonAsync("/api/orders",Cart(new CartLine(1,1))),client.PostAsJsonAsync("/api/orders",Cart(new CartLine(1,1))));Assert.Single(rs,r=>r.IsSuccessStatusCode);Assert.Single(rs,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.Equal(0,await Stock(1));Assert.Equal(1,await Orders());}
 [Fact]public async Task Receipt_omits_customer_name(){var r=await client.PostAsJsonAsync("/api/orders",Cart(new CartLine(1,1)));var o=(await r.Content.ReadFromJsonAsync<OrderDto>())!;var receipt=await client.GetStringAsync("/api/orders/"+o.Id);Assert.Contains(o.Id.ToString(),receipt);Assert.DoesNotContain("Test Shopper",receipt);}
 [Fact]public async Task Missing_api_route()=>Assert.Equal(HttpStatusCode.NotFound,(await client.GetAsync("/api/missing")).StatusCode);
 [Fact]public async Task Client_price_is_ignored(){var r=await client.PostAsJsonAsync("/api/orders",new{requestId=Guid.NewGuid(),customerName="Sample",total=.01,items=new[]{new{productId=2,quantity=1,unitPrice=.01}}});r.EnsureSuccessStatusCode();Assert.Equal(23,(await r.Content.ReadFromJsonAsync<OrderDto>())!.Total);}
}
